            queue.extend([curr * 10 + 4, curr * 10 + 7]) if curr * 10 + 4 <= n else None
            queue.extend([curr * 10 + 7]) if curr * 10 + 7 <= n else None

    lucky = sorted(candidates)

    if n == 0:
        return "-1\n"

    # DP: dp[s] = minimum number of components to achieve sum s
    dp = [float('inf')] * (n + 1)
    dp[0] = 0

    for size in components:
        for j in range(n, size - 1, -1):
            if dp[j - size] != float('inf'):
                dp[j] = min(dp[j], dp[j - size] + 1)

    # Find the minimum roads needed for each lucky number
    min_roads = float('inf')
