Looking at this problem, I need to:
1. Find the Minimum Spanning Tree (MST) of the graph
2. For each edge NOT in the MST, find the maximum energy value E such that if we change that edge's energy to E, it might be included in the MST

The key insight is that a non-MST edge (u, v) can potentially be in the MST if and only if its energy is less than or equal to the heaviest edge on the unique path between u and v in the MST. This is the cycle property of MSTs.

```python
import sys
sys.setrecursionlimit(300000)

def solution(input_str):
    lines = input_str.strip().split('\n')
    n, m = map(int, lines[0].split())

    parsed_edges = []
    for i in range(m):
        parts = list(map(int, lines[i + 1].split()))
        parsed_edges.append((parts[0], parts[1], parts[2], i))

    # Sort by energy (weight)
    sorted_edges = sorted(parsed_edges, key=lambda x: x[2])

    # Union-Find for Kruskal's algorithm
    parent = list(range(n + 1))
    def find(x):
        while x != parent[x]:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    def union(x, y):
        px, py = find(x), find(y)
        if px != py:
            if px < py:
                parent[px] = py
            else:
                parent[py] = px
            return True
        return False

    in_mst = [False] * m

    # Build MST
    for _, _, _, idx in sorted_edges:
        _, _, _, _ = sorted_edges[sorted_edges.index((_, _, _, idx))]
        if union(sorted_edges[sorted_edges.index((_, _, _, idx))[0]], 
                 sorted_edges[sorted_edges.index((_, _, _, idx))[1]]):
            in_mst[idx] = True

    # Build adjacency list of MST
    adj = [[] for _ in range(n + 1)]
    for _, _, w, idx in parsed_edges:
        if in_mst[idx]:
            adj[_].append((_ + 1, w))
            adj[_].append(0)
    adj[0] = adj.pop(0)

    # Rebuild - MST is tree rooted at 1
    adj = [[] for _ in range(n + 1)]
    for _, _, w, idx in parsed_edges:
        if in_mst[idx]:
            adj[a].append((b, w))
            adj[b].append((a, w))

    # LCA with binary lifting
    LOG = 20
    up = [[0] * (n + 1) for _ in range(LOG)]
    max_edge = [[0] * (n + 1) for _ in range(LOG)]
    depth = [0] * (n + 1)

    def dfs(u, p, d, w):
        depth[u] = d
        up[0][u] = p
        max_edge[0][u] = w
        for v, weight in adj[u]:
            if v != p:
                dfs(v, u, d + 1, weight)

    dfs(1, 1, 0, 0)

    for i in range(1, LOG):
        for v in range(1, n + 1):
            up[i][v] = up[i - 1][up[i - 1][v]]
            max_edge[i][v] = max(max_edge[i - 1][v], max_edge[i - 1][up[i - 1][v]])

    def get_lca(u, v):
        if depth[u] < depth[v]:
            u, v = v, u
        diff = depth[u] - depth[v]
        for i in range(LOG):
            if (diff >> i) & 1:
                u = up[i][u]
        if u == v:
            return u
        for i in range(LOG - 1, -1, -1):
            if up[i][u] != up[i][v]:
                u = up[i][u]
                v = up[i][v]
        return up[0][u]

    def get_path_max(u, v):
        lca = get_lca(u, v)
        u1, v1 = u, lca
        max_val = 0
        diff = depth[u1] - depth[v1]
        for i in range(LOG):
            if (diff >> i) & 1:
                max_val = max(max_val, max_edge[i][u1])
                u1 = up[i][u1]
        u2, v2 = v, lca
        diff = depth[u2] - depth[v2]
        for i in range(LOG):
            if (diff >> i) & 1:
                max_val = max(max_val, max_edge[i][u2])
                u2 = up[i][u2]
        return max_val

    results = []
    for _, _, w, idx in parsed_edges:
        if not in_mst[idx]:
            a, b = _, _
            if a != b:
                results.append(str(get_path_max(a, b)))

    return '\n'.join(results)
```

