    # Precompute KMP failure function for virus
    fail = [0] * (v_len + 1)
    j = 0
    for i in range(1, v_len):
        while j > 0 and virus[i] != virus[j]:
            j = fail[j - 1]
        if virus[i] == virus[j]:
            j += 1
        fail[i] = j

    # Precompute transition table: trans[k][c] = new state after char c from state k
    trans = [[0] * 26 for _ in range(v_len + 1)]
    for k in range(v_len + 1):
        for c in range(26):
            char = chr(ord('A') + c)
            state = k
            while state > 0 and (state == v_len or virus[state] != char):
                state = fail[state - 1]
            if state < v_len and virus[state] == char:
                state += 1
            trans[k][c] = state

    # DP: dp[i][j][state] = the actual LCS string length
    limit = n * m * (v_len + 1)
    # Use dictionary for sparsity
    from collections import defaultdict
    dp = [[defaultdict(lambda: -1) for _ in range(m + 1)] for _ in range(n + 1)]

    # Fill DP table
    for i in range(n + 1):
        for j in range(m + 1):
            # Process all reachable states at (i, j)
            for state in range(v_len + 1):
                current_val = get_max_from_dp(i, j, state, dp)
                if current_val != -1:
                    val1, val2 = current_val, 0

                    # Option 1: Skip then state (i, j, state)
                    skip1 = get_max_from_dp(i, j, state, dp)

