                i -= 1
                j -= 1
                state = prev_state
                # Backtrack from new state
                while state > 0 and state < v_len and virus[state-1] != s2[j][0] if j > 0 else True:
                    state = fail[state-1]
        elif i > 0 and dp[i][j][state] == dp[i-1][j][state]:
            i -= 1
        elif j > 0 and dp[i][j][state] == dp[i][j-1][state]:
            j -= 1
        elif state < v_len:
            state = state - 1 if virus[state] == s1[i-1] or virus[state] == s2[j-1] else fail[state-1] if state > 0 else 0
        else:
            break

    return ''.join(reversed(res))
