    competitors = []
    for i in range(1, n + 1):
        s, r = map(int, lines[i].split())
        competitors.append((s, r))

    result = []

    for i in range(n):
        min_ratio = float('-inf')
        max_ratio = float('inf')
        possible = True

        for j in range(n):
            if i == j:
                continue

            swim_i, run_i = competitors[i]
            swim_j, run_j = competitors[j]

            diff_s = 1.0 / swim_i - 1.0 / swim_j
            diff_r = 1.0 / run_i - 1.0 / run_j

            if diff_r == 0:
                if diff_s > 0:
                    possible = False
                    break
                continue

            if diff_r > 0:
                ratio = -diff_s / diff_r
                if ratio < max_ratio:
                    max_ratio = ratio
                else:
                    possible = False
                    break
            else:  # diff_r < 0
                ratio = -diff_s / diff_r
                if ratio > min_ratio:
                    min_ratio = ratio
                else:
                    possible = False
                    break

        if possible and (min_ratio < 0 or max_ratio > 0):
            result.append(i + 1)

    result.sort()
    return ' '.join(map(str, result)) + '\n'
