def solution(input_str):
    lines = input_str.strip().split('\n')
    n, r = int(lines[0].split()[0]), int(lines[0].split()[1])

    # Generate all valid integer coordinate points within distance r
    candidates = []
    for x in range(-r, r + 1):
        for y in range(-r, r + 1):
            if x*x + y*y <= r*r:
                candidates.append((x, y))

    # Sort candidates by their "value" (further from origin first)
    # This helps find good solutions early for pruning
    candidates.sort(key=lambda p: -(p[0]**2 + p[1]**2))

    best_score = -1
    best_config = []

    def dist_sq(p1, p2):
        return (p1[0] - p2[0])**2 + (p1[1] - p2[1])**2

    def calculate_score(points):
        score = 0
        m = len(points)
        for i in range(m):
            for j in range(i + 1, m):
                score += dist_sq(points[i], points[j])
        return score

    def backtrack(idx, count, current_points):
        nonlocal best_score, best_config

        # Check if we can still reach n points
        if len(candidates) - idx < n - count:
            return

        if count == n:
            score = calculate_score(current_points)
            if score > best_score:
                best_score = score
                best_config = list(current_points)
            return

        # Try adding point at index i (and skip to avoid duplicates)
        for i in range(idx, len(candidates)):
            current_points.append(candidates[i])
            backtrack(i + 1, count + 1, current_points)
            current_points.pop()

    # Start the search for each starting point
    for start_idx in range(len(candidates)):
        backtrack(start_idx, 0, [])

    # Return result
    result_lines = [str(best_score)]
    for x, y in best_config:
        result_lines.append(f"{x} {y}")

    return '\n'.join(result_lines)
