Looking at this problem, I need to determine if a game of coin splitting among pirates around a table will eventually end or cycle infinitely.

The key insight is:
- The game ends when no pirate has ≥ 2 coins (everyone has 0 or 1 coin)
- If we can find a sequence of moves that leads to this state, output '1'
- If all possible move sequences loop forever, output '-1'

I'll use BFS with cycle detection to explore the state space and determine if a terminal state is reachable.

```python
from collections import deque

def solution(input_str):
    lines = input_str.strip().split('\n')
    if not lines:
        return '-1'

    n, k = map(int, lines[0].split())

    coins = [0] * n

    # Parse the k lines of coin assignments
    for line in lines[1:k+1]:
        parts = line.split()
        if len(parts) >= 2:
            a, b = int(parts[0]), int(parts[1])
            if 1 <= a <= n:
                coins[a - 1] = b

    visited = set()
    queue = deque()

    start_state = tuple(coins)
    visited.add(start_state)
    queue.append(start_state)

    def is_terminal(state):
        return all(c <= 1 for c in state)

    def get_next_states(state):
        eligible = [i for i, c in enumerate(state) if c >= 2]
        if not eligible:
            return None  # Terminal

        states = []
        for i in eligible:
            new_coins = list(state)
            new_coins[i] -= 2

            if i == 0:
                new_coins[n - 1] += 1
            elif i == n - 1:
                new_coins[0] += 1
            else:
                new_coins[i - 1] += 1
                new_coins[i + 1] += 1

            states.append(tuple(new_coins))

        return states

    while queue:
        state = queue.popleft()

        if is_terminal(state):
            return '1'

        next_states = get_next_states(state)
        if next_states is None:
            return '1'  # No more candidates - terminal

        for new_state in next_states:
            if new_state not in visited:
                visited.add(new_state)
                queue.append(new_state)

            # Safety: if too many states visited, likely cycling
            if len(visited) > 100000:
                return '-1'

    # If we exhaust the search without finding terminal state, it's a bad game
    return '-1'
