import os
from collections import deque

def solution(input_str):
    lines = input_str.strip().split('\n')
    n, k = map(int, lines[0].split())
    s = lines[1]

    # BFS to find valid path
    # State: (index, wins, loses)
    # We track the path to reconstruct the sequence

    # visited states
    visited = set()
    visited.add((0, 0, 0))

    queue = deque()
    queue.append((0, 0, 0, []))  # (index, wins, loses, path)

    while queue:
        idx, wins, loses, path = queue.popleft()

        if idx == n:
            if abs(wins - loses) == k:
                return ''.join(path)
            continue

        # Determine possible moves for current position
        if s[idx] == '?':
            moves = ['W', 'L', 'D']
        else:
            moves = [s[idx]]

        for move in moves:
            if move == 'W':
                next_wins = wins + 1
                next_loses = loses
            elif move == 'L':
                next_wins = wins
                next_loses = loses + 1
            else:
                next_wins = wins
                next_loses = loses

            diff = abs(next_wins - next_loses)
            # Can't have difference k before the end
            if diff == k:
                continue

            next_state = (idx + 1, next_wins, next_loses)
            if next_state not in visited:
                visited.add(next_state)
                queue.append((idx + 1, next_wins, next_loses, path + [move]))

    return 'NO\n'

