                 (1, -1),  (1, 0),  (1, 1)]

    # Check immediate conflicts
    for i in range(n):
        for j in range(m):
            if grid[i][j] != '0':
                for di, dj in neighbors:
                    ni, nj = i + di, j + dj
                    if 0 <= ni < n and 0 <= nj < m:
                        if grid[ni][nj] != '0' and grid[ni][nj] == grid[i][j]:
                            return "0\n"

    # Fill zeros using backtracking
    sys.setrecursionlimit(2000000)

    def backtrack(idx):
        if idx == n * m:
            return True

        i, j = idx // m, idx % m

        if grid[i][j] == '0':
            for c in ['1', '2', '3', '4']:
                valid = True
                for di, dj in neighbors:
                    ni, nj = i + di, j + dj
                    if 0 <= ni < n and 0 <= nj < m and grid[ni][nj] == c:
                        valid = False
                        break
                if valid:
                    grid[i][j] = c
                    if backtrack(idx + 1):
                        return True
                    grid[i][j] = '0'

        return False

    if backtrack(0):
        return '\n'.join(''.join(row) for row in grid) + '\n'
    return "0\n"
