    matrix = [list(lines[i+1]) for i in range(n)]

    # Precompute which row segments can form palindromes
    # row_seg[i][j1][j2] = True if row i, columns j1 to j2 can form a palindrome
    row_seg = [[[False] * m for _ in range(m)] for _ in range(n)]
    for i in range(n):
        for j1 in range(m):
            freq = [0] * 26
            odd_count = 0
            for j2 in range(j1, m):
                char_idx = ord(matrix[i][j2]) - ord('a')
                freq[char_idx] += 1
                if freq[char_idx] % 2 == 1:
                    odd_count += 1
                row_seg[i][j1][j2] = odd_count <= 1

    count = 0
    # Check all possible submatrices
    for i1 in range(n):
        for i2 in range(i1, n):
            # Find column-range pairs that work for both rows in the range
            compatible_cols = []
            for j1 in range(m):
                for j2 in range(j1, m):
                    if i1 == i2:
                        # Single row - check if this row segment works
                        if row_seg[i1][j1][j2]:
                            compatible_cols.append((j1, j2))
                    else:
                        # Multiple rows - check if both rows support this column range
                        if row_seg[i1][j1][j2] and row_seg[i2][j1][j2]:
                            compatible_cols.append((j1, j2))

            if not compatible_cols:
                continue

            for (j1, j2) in compatible_cols:
                # Check if all columns in this range can form palindromes
                col_ok = True
                for c in range(j1, j2 + 1):
                    freq = [0] * 26
                    odd_count = 0
                    for r in range(i1, i2 + 1):
