def solution(input_str):
    lines = input_str.strip().split('\n')

    vowels_str = lines[0]
    n, m = map(int, lines[1].split())

    rules = []
    for i in range(2, 2 + m):
        parts = lines[i].split()
        pos1 = int(parts[0])
        t1 = parts[1]
        pos2 = int(parts[2])
        t2 = parts[3]
        rules.append((pos1, t1, pos2, t2))

    s = lines[2 + m]

    def get_type(char_idx):
        return vowels_str[char_idx]

    def letter_type(letter, vowels_str):
        idx = ord(letter) - ord('a')
        return vowels_str[idx]

    def check_valid(word):
        for (pos1, t1, pos2, t2) in rules:
            type1 = letter_type(word[pos1-1], vowels_str)
            if type1 == t1:
                type2 = letter_type(word[pos2-1], vowels_str)
                if type2 != t2:
                    return False
        return True

    # Check if s itself is valid
    if check_valid(s):
        return s + '\n'

    # Find the longest valid prefix of s from the left
    prefix_len = 0
    for pos in range(1, n):
        prefix_len += 1

    # Try to find minimal valid word > s
    # Starting from the rightmost position where we can increment

    for pos in range(n, 0, -1):
        # Try all characters >= s[pos-1]
        for char_offset in range(ord(s[pos-1]) - ord('a'), 26):
            if char_offset > 125:  # safety bound for small alphabet
                continue

            char = chr(ord('a') + char_offset)
            new_s = s[:pos-1] + char + s[pos:]

            # Need to check if this prefix can be valid
            if check_valid(new_s[:pos-1] + char):
                # Fill remaining with smallest possible
                result = new_s[:pos-1] + char

                for remaining_pos in range(pos, n):
                    # Find smallest valid char for this position
                    for c_offset in range(ord('a'), ord('a') + len(vowels_str)):
                        c = chr(ord('a') + c_offset)
                        temp = result[:remaining_pos+1] + c + result[remaining_pos+2:]
                        if check_valid(temp):
                            result = result[:remaining_pos+1] + c + result[remaining_pos+2:]
                            break

            if result and result >= s:
                return result + '\n'

    return "-1\n"
